mapper.select:

SELECT v.voucher_id
  FROM pay_voucher v
 WHERE v.summary_note = #{token}

WITH base_ps AS ( /* 대상 payslip + emp + dept (사번 필터 포함) / 対象 payslip + emp + dept（社員番号フィルタを含む） */ SELECT p.payslip_id, e.emp_id, d.dept_id, d.dept_code, d.dept_name FROM payslip p JOIN emp e ON e.emp_id = p.emp_id JOIN dept d ON d.dept_id = e.dept_id WHERE p.apply_yyyymm = #{yyyymm} AND p.pay_type = #{payType}
AND e.emp_no IN (
#{no}
)
), earn_sum AS ( /* 지급합계(부서별) / 支給合計（部署別） */ SELECT b.dept_id, NVL(SUM(i.amount),0) AS pay_sum FROM base_ps b LEFT JOIN payslip_item i ON i.payslip_id = b.payslip_id GROUP BY b.dept_id ), ded_sum AS ( /* 공제합계(부서별) / 控除合計（部署別） */ SELECT b.dept_id, NVL(SUM(dd.amount),0) AS ded_sum FROM base_ps b LEFT JOIN payslip_deduction dd ON dd.payslip_id = b.payslip_id GROUP BY b.dept_id ), agg_sum AS ( /* 부서별 지급/공제/순액 / 部署別 支給・控除・純額 */ SELECT NVL(e.dept_id, d.dept_id) AS dept_id, NVL(e.pay_sum,0) AS pay_sum, NVL(d.ded_sum,0) AS ded_sum, NVL(e.pay_sum,0) - NVL(d.ded_sum,0) AS net_sum FROM earn_sum e FULL OUTER JOIN ded_sum d ON d.dept_id = e.dept_id ), vrows AS ( /* ← 예약어 회피: rows → vrows / 予約語回避：rows → vrows */ /* 차변: 급여비용(D) / 借方：給与費用(D) */ SELECT #{wageAcct} AS account_id, 'D' AS drcr_code, a.dept_id, a.pay_sum AS debit_amt, 0 AS credit_amt, 'PAY' AS cost_type_code, 'PAYVCH-'||#{yyyymm}||'-'||#{payType}||'#ACCRUAL' AS summary_note FROM agg_sum a
UNION ALL
/* 대변: 예수금(C) / 貸方：預り金(C) */ SELECT #{withholdAcct}, 'C', a.dept_id, 0, a.ded_sum, 'TAX', 'PAYVCH-'||#{yyyymm}||'-'||#{payType}||'#ACCRUAL' FROM agg_sum a
UNION ALL
/* 대변: 미지급급여(C) = 실지급 / 貸方：未払給与(C)＝実支給 */ SELECT #{accruedAcct}, 'C', a.dept_id, 0, GREATEST(a.net_sum, 0), 'NET', 'PAYVCH-'||#{yyyymm}||'-'||#{payType}||'#ACCRUAL' FROM agg_sum a ) SELECT /* ─ 화면 컬럼 매핑 (VoucherLedgerRowMap) ─ / 画面列マッピング（VoucherLedgerRowMap） */ TO_CHAR( ROW_NUMBER() OVER ( ORDER BY CASE r.drcr_code WHEN 'D' THEN 0 ELSE 1 END, NVL(dp.dept_code,'ZZZ'), /* 대변 내부: 예수금 → 미지급 / 貸方内部：預り金 → 未払 */ CASE WHEN r.drcr_code='C' AND r.account_id = #{accruedAcct} THEN 1 ELSE 0 END, r.account_id ) ) AS display_seq, -- 화면 번호 / 表示番号 r.account_id AS account_id, -- accountName/accountCode 둘 다 매핑 / 両方に同値マッピング CASE r.drcr_code WHEN 'D' THEN '借方' ELSE '貸方' END AS drcr_name, r.debit_amt AS debit_amt, r.credit_amt AS credit_amt, dp.dept_name AS occur_dept_name, TO_CHAR(LAST_DAY(TO_DATE(#{yyyymm}||'-01','YYYY-MM-DD')), 'YYYY-MM-DD') AS occur_date, TO_CHAR(LAST_DAY(TO_DATE(#{yyyymm}||'-01','YYYY-MM-DD')), 'YYYY-MM-DD') AS pay_date_str, r.summary_note AS summary_note, NULL AS voucher_no, 'N' AS approved_yn, ROW_NUMBER() OVER (ORDER BY 1) AS line_seq, r.account_id AS account_id, -- (내부코드 재사용) / （内部コード再利用） r.drcr_code AS drcr_code, dp.dept_code AS occur_dept_code, r.cost_type_code AS cost_type_code, 0 AS process_flag, dp.dept_code AS target_code FROM vrows r JOIN dept dp ON dp.dept_id = r.dept_id ORDER BY CASE r.drcr_code WHEN 'D' THEN 0 ELSE 1 END, NVL(dp.dept_code,'ZZZ'), CASE WHEN r.drcr_code='C' AND r.account_id = #{accruedAcct} THEN 1 ELSE 0 END, r.account_id

mapper.delete:

DELETE FROM pay_voucher_line
 WHERE voucher_id IN (
   SELECT v.voucher_id
     FROM pay_voucher v
    WHERE v.summary_note = #{token}
 )
